package com.supportsphere.controller; import com.supportsphere.model.*; import com.supportsphere.dao.*; import com.supportsphere.service.*; import com.supportsphere.util.*; import javafx.fxml.*; import javafx.collections.*; import javafx.scene.control.*; import javafx.scene.control.cell.PropertyValueFactory; import java.util.*;
public class RequesterDashboardController { @FXML Label welcome,total,open,active,completed,notificationCount; @FXML TableView<AssistanceRequest> table; @FXML TableColumn<AssistanceRequest,String> idCol,taskCol,urgencyCol,statusCol,dateCol,volCol; private final RequestService service=new RequestService(); private final FeedbackDAO feedback=new FeedbackDAO(); @FXML void initialize(){load();} private void load(){try{User u=Session.getUser();welcome.setText("Good day, "+u.getName().split(" ")[0]+" 👋");List<AssistanceRequest>x=service.mine(u.getUserId());table.setItems(FXCollections.observableArrayList(x));idCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty("#"+c.getValue().getRequestId()));taskCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getTaskType()));urgencyCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getUrgency().name()));statusCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getStatus().name().replace('_',' ')));dateCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getPreferredDate()+" · "+c.getValue().getStartTime()));volCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getVolunteerName()==null?"Awaiting volunteer":c.getValue().getVolunteerName()));long o=x.stream().filter(r->r.getStatus()==RequestStatus.OPEN).count(),a=x.stream().filter(r->r.getStatus()==RequestStatus.ASSIGNED||r.getStatus()==RequestStatus.IN_PROGRESS).count(),c=x.stream().filter(r->r.getStatus()==RequestStatus.COMPLETED).count();total.setText(""+x.size());open.setText(""+o);active.setText(""+a);completed.setText(""+c);notificationCount.setText(""+new NotificationDAO().count(u.getUserId()));}catch(Exception e){Dialogs.error("Dashboard error",e.getMessage());}} @FXML void create(){try{SceneManager.show("create-request.fxml","SupportSphere — New assistance request");}catch(Exception e){Dialogs.error("Navigation error",e.getMessage());}} @FXML void details(){AssistanceRequest r=table.getSelectionModel().getSelectedItem();if(r==null){Dialogs.info("Select a request","Choose a request from the table first.");return;}try{String h=String.join("\n\n",service.history(r.getRequestId()));String msg="Task: "+r.getTaskType()+"\nLocation: "+r.getLocationLabel()+"\nWhen: "+r.getPreferredDate()+" · "+r.getStartTime()+"–"+r.getEndTime()+"\nStatus: "+r.getStatus()+"\nVolunteer: "+(r.getVolunteerName()==null?"Awaiting volunteer":r.getVolunteerName())+"\n\nDescription:\n"+r.getDescription()+"\n\nTimeline:\n"+(h.isBlank()?"Request created — history will appear as it progresses.":h);Dialogs.info("Request #"+r.getRequestId(),msg);}catch(Exception e){Dialogs.error("Could not load request",e.getMessage());}} @FXML void cancel(){AssistanceRequest r=table.getSelectionModel().getSelectedItem();if(r==null||r.getStatus()!=RequestStatus.OPEN){Dialogs.info("Cancellation unavailable","Only open requests can be cancelled from here.");return;}String reason=Dialogs.text("Cancel request","Why are you cancelling this request?");if(reason.isBlank())return;try{service.cancel(r.getRequestId(),Session.getUser().getUserId(),reason);load();}catch(Exception e){Dialogs.error("Could not cancel",e.getMessage());}} @FXML void feedback(){AssistanceRequest r=table.getSelectionModel().getSelectedItem();if(r==null||r.getStatus()!=RequestStatus.COMPLETED){Dialogs.info("Feedback unavailable","Feedback is available after a request is completed.");return;}try{if(feedback.exists(r.getRequestId())){Dialogs.info("Already reviewed","You have already submitted feedback for this request.");return;}Optional<Integer>v=new AssignmentDAO().volunteerForRequest(r.getRequestId());if(v.isEmpty()){Dialogs.error("Feedback error","No volunteer assignment was found.");return;}TextInputDialog rating=new TextInputDialog("5");rating.setTitle("Rate your volunteer");rating.setHeaderText("Enter a rating from 1 to 5");int rt=Integer.parseInt(rating.showAndWait().orElse("0"));if(rt<1||rt>5)throw new IllegalArgumentException("Rating must be 1–5.");String comment=Dialogs.text("Feedback","Share a short comment (optional).");feedback.save(new Feedback(r.getRequestId(),Session.getUser().getUserId(),v.get(),rt,comment));Dialogs.info("Thank you","Your feedback has been recorded.");load();}catch(Exception e){Dialogs.error("Could not submit feedback",e.getMessage());}} @FXML void notifications(){try{NotificationDAO n=new NotificationDAO();List<String>x=n.unread(Session.getUser().getUserId());Dialogs.info("Notifications",x.isEmpty()?"You're all caught up.":String.join("\n\n",x));n.markRead(Session.getUser().getUserId());load();}catch(Exception e){Dialogs.error("Notifications error",e.getMessage());}} @FXML void logout(){Session.clear();try{SceneManager.show("login.fxml","SupportSphere — Sign in");}catch(Exception e){}} }
